Pk={'P':P,'P2':P**2,'P3':P**3,'1':P*0+1,'1/P':1/P}
tk={'1':t*0+1,'t':t,'t2':t**2,'e-t':np.exp(-t),'sin':np.sin(t),'cos':np.cos(t),'logt':np.log(t),'sqrt':np.sqrt(t),'1/t':1/t}
