            cols[a+'*'+b]=fa*fb
    return cols
names=list(build(1,1).keys())
def resid(q):
    cols=build(q[0],q[1])
    B=np.column_stack([cols[n] for n in names])
    c=np.linalg.lstsq(B,y,rcond=None)[0]
    return B@c-y
